/* ---------- scenarios ---------- */
var S=[
 {id:"start",name:"Start the program",sum:"From double-click to every plugin running and what happens when a check fails.",
  steps:[
   {t:"You launch hetu",n:["human","runtime","boot"],e:["human_launch","runtime_boot"],x:"The runtime runs first, before Electron is ready. A packaged build exits on a debugging switch. Only one hetu runs per data folder, so a second start opens or focuses a window in the first and quits. The sandbox is on for every renderer before any plugin code can run. Then boot takes over.",c:["Debugging switches refused","One instance per data folder"],th:[42]},
   {t:"Boot sets up trust",n:["boot","lockm","state","lanes"],e:["boot_lock","boot_state","boot_lanes"],x:"Boot takes the folder lock, opens the one event log and loads the security state. It checks each state file against the hash on its last line before the strict parser reads it. A plugin entry that fails doesn't load and nothing else stops. Edited switches fall back to every guard on. A program running as you can edit the files, so the hash catches careless edits, not one that rewrites the hash too.",c:["Hash line checked","Duplicate keys and unknown types rejected"],th:[24,25,54]},
   {t:"Check the install",n:["boot","loader","runtime","install"],e:["boot_loader","loader_install"],x:"The runtime makes a session per role, each in memory and offline with deny-all permission handlers. Boot hands the state to the loader, which reads the install list and hashes each host-level and in-page plugin against it. A mismatch refuses that plugin alone.",c:["Install plugins checked against the install list"],th:[24,49]},
   {t:"Host-level plugins start",n:["loader","carrier","lockm","log","gate","capabilities","watchdog","storage","luoshu","history","exec","leases"],e:["loader_lock","loader_carrier","loader_gate"],x:"The carrier starts with every action that has power answering starting. The log, the gate with StateView 1, capabilities and the watchdog come up first, then storage, the luoshu, history, exec and leases, one at a time. A start marker sits beside each until it is ready, so one that freezes main can't lock you out at the next boot.",c:["Slot holders first","Start markers"],th:[35,39]},
   {t:"Open the editor window",n:["runtime","eshell","ecore","gate","luoshu"],e:["runtime_shell"],x:"The editor window opens once the gate and the luoshu have each settled: ready, off, failed or absent. The shell gets its verbs from the gate and shows the banner. Saves answer starting until the guards are ready, while your text stays in a draft.",c:["Opens on settled states","The window can't touch disk"],th:[42]},
   {t:"Check every folder plugin",n:["loader","install","pfolder","capabilities"],e:["loader_pfolder","loader_caps"],x:"The loader brings the first-party copies in step with the install, then scans the plugin folder. It reads and hashes each plugin's files once, applies the signer pairing and the reserved ids and parses each manifest with the strict parser. Every result goes in the log. A folder with no entry becomes a new plugin request, never a silent load.",c:["Hash once, run the hashed bytes","A record for every result"],th:[24,26,32]},
   {t:"Start sandboxed plugins",n:["loader","runtime","whost","gitp","search","fexp","mcp","httpl"],e:["loader_runtime","runtime_whost","runtime_http"],x:"The runtime creates the first-party hidden renderer and waits for its worker host page. Git, search and the file explorer start as data: workers in graph order, each holding exactly its approved grants. MCP starts in its own renderer and the http plugin binds once MCP is ready.",c:["data: workers from the verified bytes","requires resolved first"],th:[29,35]},
   {t:"Record the start",n:["carrier","lanes","logs"],e:["lanes_logs"],x:"A core.ready floor record names every slot's state. From here a slot that isn't ready reports down. With the optional cloud plugin, a copy leaves the machine.",c:["Hash chain"],th:[11]},
   {t:"If any check failed",n:["boot","loader","pfolder","state","trusted"],e:["loader_pfolder","boot_state"],x:"A failed check never means a silent start. The suspect plugin stays off with its reason in the plugin list, edited switches fall back to every guard on and the result is in the log. A first-party copy can be restored from the install. A notification plugin raises the alert, since the banner shows only security states.",c:["Fail closed","Reason in the plugin list"],th:[39],bad:true}
  ]},
 {id:"install",name:"Install a plugin",sum:"From a developer's release to the plugin up and running on your machine.",
  steps:[
   {t:"Developer signs a release",n:["dev","internet"],e:["dev_internet"],x:"The developer's GitHub workflow signs the release keylessly with Sigstore. The signature lands in Rekor, the public append-only log. The signer identity is the repo plus workflow.",c:["No long-lived key to steal"],th:[48]},
   {t:"You add it to the plugin folder",n:["human","internet","pfolder"],e:["internet_pfolder","human_pfolder"],x:"You download the package with its signature file into the one plugin folder. Nothing loads yet.",c:["A file in the folder is not an approval"],th:[]},
   {t:"hetu notices a new plugin",n:["loader","pfolder"],e:["loader_pfolder"],x:"At start or on a rescan the loader finds a folder with no state entry. It reads and hashes the files once, parses the manifest with the strict parser and raises a new plugin request itself. An agent dropping a plugin in hits the same request.",c:["Never a silent load","Unknown capability types refused"],th:[27,54]},
   {t:"Classify it",n:["loader","capabilities"],e:["loader_caps"],x:"The capabilities plugin computes the class from everything the plugin can reach, never from what it declares. It also writes the screen text. Read plus network together ranks class 4.",c:["Class computed, never declared","Combination rules"],th:[27]},
   {t:"See exactly what it asks for",n:["runtime","trusted"],e:["runtime_trusted"],x:"The runtime opens the trusted window with the request. The page draws the change from the core's own text first, then the capabilities screen as plain text, the signer and every permission. Approval is all or nothing, so the permission design stays with the plugin's maker.",c:["All or nothing","Signer shown"],th:[33]},
   {t:"Approve with a Confirm click",n:["human","trusted","carrier"],e:["human_trusted","trusted_carrier"],x:"You click Confirm once it arms. The carrier counts it only from the trusted window's top frame on hetu://trusted, checked first. If a state file changed since the request, the answer is stale and nothing applies.",c:["Only Confirm in the trusted window approves"],th:[22,33]},
   {t:"Record first, then write the state",n:["carrier","lanes","logs","loader","state","gate"],e:["carrier_loader","lanes_logs","loader_state","loader_gate"],x:"The core writes the Confirm record. Once it is on disk the loader applies exactly the stored change: the plugin's entry with its hash, pinned signer, grants and class. The gate gets a new StateView.",c:["Widening applies after its record","Signer pinned on first use"],th:[11,47]},
   {t:"Start the plugin",n:["loader","carrier","runtime","community"],e:["loader_carrier","loader_runtime","runtime_comm"],x:"The loader mints the plugin's port and registers it with the carrier in the same step. The runtime starts it as a data: worker in a hidden renderer of its own, from the bytes the loader hashed. Its views mount in the editor window when you open one.",c:["Worker sandbox","Grants from the security state"],th:[26,29]},
   {t:"Its first request",n:["community","carrier","gate","lanes"],e:["comm_carrier","carrier_gate","carrier_lanes"],x:"Every action the plugin takes is a call the carrier checks, the gate decides and the log records. It has no power of its own.",c:["Precheck before route","Recorded"],th:[30,31]}
  ]},
 {id:"update",name:"A plugin update arrives",sum:"Which updates load without a prompt, which ask you and when hetu warns.",
  steps:[
   {t:"A new version appears",n:["dev","internet","pfolder"],e:["dev_internet","internet_pfolder"],x:"The developer publishes a new signed release. It is staged beside the old version, never over it.",c:[],th:[]},
   {t:"Same signer?",n:["loader","pfolder","state"],e:["loader_pfolder"],x:"The loader compares the signer identity with the one pinned at first approval. A different identity, even with a valid signature, is treated as a new plugin with a warning. That stops a forked plugin with a backdoor.",c:["Signer must match the pin"],th:[47]},
   {t:"Does it still fit?",n:["loader"],e:[],x:"The loader resolves the update against the live plugin graph. One that closes a cycle or leaves a running plugin without what it requires is refused or needs a Confirm naming the plugins it stops.",c:["Resolved against the live graph"],th:[]},
   {t:"Class 0 loads without a prompt",n:["loader","capabilities","community"],e:["loader_caps"],x:"Only an update with no privilege, class 0, skips the Confirm and only while the capabilities plugin allows it. An update that asks for more needs your approval again, whatever its class.",c:["Only class 0 skips the Confirm","Widened manifest asks again"],th:[28,48]},
   {t:"Everything else asks you",n:["human","trusted","carrier","loader","state"],e:["human_trusted","trusted_carrier","carrier_loader","loader_state"],x:"For class 1 and up you approve the update with a Confirm click. Its record lands first, then the loader writes the entry.",c:["A Confirm click per update"],th:[48]},
   {t:"Swap and restart",n:["loader","pfolder","runtime","community"],e:["loader_pfolder","loader_runtime","runtime_comm"],x:"The staged folder is swapped in and the state entry written last. The old incarnation stops and the new one starts on a new port. A crash between the swap and the entry reads as a failed check.",c:["Entry written last"],th:[26]},
   {t:"First-party never comes this way",n:["loader","install","pfolder"],e:["loader_install","loader_pfolder"],x:"Host-level and in-page plugins change only with an app update. The loader checks each against the install list and clears its cache when the version changes. First-party folder plugins are copied from the install at start, never fetched through the plugin channel.",c:["Core ships inside the app install"],th:[49]}
  ]},
 {id:"agent",name:"An agent edits a note",sum:"First connection, consent, lease, edit, commit and the events that follow.",
  steps:[
   {t:"First call without a token",n:["agent","httpl"],e:["agent_http"],x:"The agent calls hetu's MCP endpoint on 127.0.0.1. With no token it gets a 401 and the Protected Resource Metadata pointing at hetu's authorization server.",c:["Loopback only, Host and Origin checks"],th:[14,15]},
   {t:"OAuth with PKCE",n:["agent","oauth","internet"],e:["agent_oauth","oauth_internet"],x:"The agent starts OAuth 2.1 with PKCE. If it identifies with a client metadata URL, hetu fetches it over HTTPS only and never from private or loopback addresses.",c:["HTTPS only","No private addresses"],th:[51]},
   {t:"You consent once",n:["human","trusted","mcp","carrier","storage","storefs"],e:["mcp_carrier","carrier_storage","storage_fs"],x:"You approve the agent and set its grants. The MCP plugin keeps the agent's grants in its own storage, so an agent never gets more than the MCP plugin holds. How the consent reaches the Confirm click in the trusted window is settled when the MCP plugin is built.",c:["Agent grants in the MCP plugin's storage"],th:[9]},
   {t:"Short-lived token",n:["oauth","agent","oauthst"],e:["agent_oauth","oauth_state"],x:"The agent receives a short-lived access token bound to hetu. Its harness stores the token, not hetu. Refresh tokens rotate and reuse of an old one revokes the chain and alerts you.",c:["Short-lived","Reuse detection"],th:[50]},
   {t:"The call reaches MCP",n:["agent","httpl","carrier","mcp"],e:["agent_http","http_carrier","carrier_mcp"],x:"http calls mcp.handle over its own port with the agent's client id as onBehalf. Only http may call that action, so no plugin can pose as an agent. The label goes to the callee, the guards and the log, but the gate never decides on it.",c:["Only http reaches mcp.handle","onBehalf grants nothing"],th:[9,40]},
   {t:"Ask for a lease",n:["mcp","carrier","gate","leases"],e:["mcp_carrier","carrier_gate","carrier_leases"],x:"The MCP plugin checks the agent's grant and calls leases.acquire with the same onBehalf. The gate checks the MCP plugin's own luoshu.write grant on the paths. Leases keys the holder by caller plus onBehalf, so a second agent can't write under the first one's lease.",c:["Agent grants inside the MCP plugin's"],th:[1,6,40]},
   {t:"Refused? Only a code",n:["leases","mcp"],e:[],x:"If another writer holds the note, the refusal carries a fixed code, never another agent's lease or id. That's the A-05 lesson.",c:["A refusal names nothing of another caller"],th:[6,37]},
   {t:"Edit the note",n:["mcp","carrier","gate","luoshu","leases","luoshufs"],e:["mcp_carrier","carrier_gate","carrier_luoshu","carrier_leases","luoshu_luoshufs"],x:"luoshu.write takes the eleven steps. The gate's precheck passes, the luoshu turns the path into a canonical one and takes its per-path lock, the gate decides on it and the lease guard confirms the holder. Then the luoshu checks the version and writes the file.",c:["Canonical path before decide","Lease holder only","Version check"],th:[1,2,3]},
   {t:"Tell the others",n:["luoshu","bus","gate","search","eshell"],e:["luoshu_bus","bus_gate","bus_hidden","bus_shell"],x:"The luoshu publishes luoshu.changed. The bus asks the gate's canRead for each subscriber and sends a signal plus the path, never the content, to the search indexer and an open editor.",c:["canRead on every delivery"],th:[37]},
   {t:"Commit to the shadow repo",n:["carrier","history","osproc","shadow","luoshufs"],e:["carrier_history","history_proc","proc_shadow","proc_luoshu"],x:"The history plugin commits the edit under the agent's label in hetu's own repo, with git plumbing only and a clean environment. Your own repo is untouched. Whether leases or git asks for that commit is settled when both are built.",c:["Plumbing only","Luoshu git config never read"],th:[13,45]},
   {t:"Everything was recorded",n:["carrier","lanes","log","logs"],e:["carrier_lanes","log_lanes","lanes_logs"],x:"Each call above is an audit record with the caller, the agent's label and the outcome. The log plugin writes the records in batches behind the core's own floor records.",c:["Hash chain"],th:[11]}
  ]},
 {id:"type",name:"You type, a plugin decorates",sum:"The editor core, the bridge, edits from a plugin and saving as your window.",
  steps:[
   {t:"You type",n:["human","ecore"],e:["human_ecore"],x:"Keystrokes go straight to the editor core. Hidden marks re-hide markdown markers at once, since that code runs inside the page, compiled in from the install.",c:["Hidden marks in-page"],th:[]},
   {t:"Plugins hear about it",n:["ecore","eshell","views"],e:["shell_views"],x:"The bridge tells each view frame that holds the verb that the document changed.",c:["Granted verbs only"],th:[41]},
   {t:"A plugin sends decorations",n:["views","eshell","ecore"],e:["views_shell","shell_ecore"],x:"A search-highlight plugin's editor half sends CodeMirror-shaped decoration specs. The bridge checks ranges, allows theme styles only and accepts widgets only as text or a frame.",c:["Theme styles only","No HTML widgets"],th:[19,41]},
   {t:"A plugin sends an edit",n:["views","eshell","ecore"],e:["views_shell","shell_ecore"],x:"A table formatter sends a change list against document version N. If you typed since, the version is stale and the edit is refused. An accepted edit is attributed to the plugin.",c:["Version check","Attributed to the plugin"],th:[41]},
   {t:"Save as your window",n:["ecore","carrier","gate","luoshu","leases","luoshufs"],e:["ecore_carrier","carrier_gate","carrier_luoshu","carrier_leases","luoshu_luoshufs"],x:"The editor core saves over window IPC. The carrier checks the sender first and then the window's fixed grants. The save takes the same steps as every other write and is recorded as yours. Your draft stays until the save lands.",c:["Sender checked first","Attributed to you"],th:[19,42]},
   {t:"Raw view tells the truth",n:["human","ecore"],e:["human_ecore"],x:"Ctrl+/ switches to the raw view, which ignores every plugin decoration. A decoration can never hide text from you there.",c:["Raw view in-page, unreachable by plugins"],th:[8]}
  ]},
 {id:"guardoff",name:"Switch security off",sum:"How you switch security off on purpose, what still holds and why nothing else can.",
  steps:[
   {t:"You choose to switch it off",n:["human","trusted"],e:["human_trusted"],x:"The switches in the trusted window cover every plugin, the gate and the log included. Only a hetu window can ask for a change, never a plugin or MCP.",c:["Never over MCP, never by a plugin"],th:[22]},
   {t:"The request",n:["trusted","carrier"],e:["trusted_carrier"],x:"The window sends security.request. The core reads from the change's structure whether it widens. Switching the gate or a guard off widens, so it waits for a Confirm. The security path never asks the gate, so a failed gate can't block it.",c:["security actions refused for every plugin","Never asked of the gate"],th:[22,39]},
   {t:"Your Confirm click",n:["human","trusted","carrier"],e:["human_trusted","trusted_carrier"],x:"The page draws the exact change. Confirm arms after a short delay and counts only from the trusted window's top frame.",c:["Your Confirm click"],th:[33]},
   {t:"Record first, then apply",n:["carrier","lanes","logs","loader","state","gate"],e:["carrier_loader","lanes_logs","loader_state","loader_gate"],x:"The core writes who switched what and when. Once that record is on disk the loader writes the switch into the per-machine state, never into the luoshu. Plugins start or stop to match and subscriptions are asked again.",c:["Applies after its record","Per machine"],th:[11,22]},
   {t:"A banner while it's off",n:["eshell","trusted"],e:[],x:"Every window's shell shows what is off for as long as it stays off. The trusted window says that per-item switches lapse while the gate is off.",c:["Visible state"],th:[22]},
   {t:"Gate off: allow all, still logged",n:["carrier","gate","log","lanes","logs"],e:["carrier_lanes","log_lanes","lanes_logs"],x:"Calls with power skip the gate. The floor and the guards still hold and exec still checks each plugin's declared commands. While the gate is off, calls with power need the log running. If the log is down, such calls are refused unless you switched the log off too.",c:["Floor and guards still hold","No log, no pass"],th:[11,45]},
   {t:"Three more switches",n:["trusted","exec","carrier","lanes"],e:[],x:"exec can run any command for a plugin you name. Limits can be raised per plugin or for all. Recording can be switched off and that switch is the last record until recording is back on. Each widens, so each needs a Confirm and shows in the banner. No switch hands a plugin or an agent a power the framework doesn't have.",c:["A Confirm and the banner for each","No switch gives a plugin Node or a security change"],th:[22]},
   {t:"A crash is not a switch",n:["gate","leases","carrier"],e:["carrier_gate","carrier_leases"],x:"A gate or a guard that is missing, crashed or failed its check without you switching it off fails closed. Only your click turns security off.",c:["Fail closed"],th:[39],bad:true}
  ]},
 {id:"gatedown",name:"The gate fails",sum:"What happens when the gate crashes without you switching it off and the way back.",
  steps:[
   {t:"The gate throws",n:["carrier","gate"],e:["carrier_gate"],x:"A throw inside decide or canRead refuses that one call and the fault is recorded. A start that throws or times out, or a throw when a new StateView arrives, marks the gate failed for the rest of the run, since a restart would rerun the code that broke.",c:["A throw refuses","No restart within a run"],th:[39]},
   {t:"Calls with power fail closed",n:["carrier","gate","community","mcp","ecore"],e:["comm_carrier","carrier_gate"],x:"Calls with power answer policy-down, deputy checks included. Windows get no luoshu access. Plugins keep running and see a refusal code, as with any refusal.",c:["policy-down","Plugins keep running"],th:[39]},
   {t:"Events wait",n:["bus","gate","search"],e:["bus_gate","bus_hidden"],x:"canRead answers false while the gate is down, so path events are held back and new subscriptions wait. Once the gate allows delivery again, each path subscriber gets one events.dropped to resync.",c:["Path events held back"],th:[37]},
   {t:"The banner shows it",n:["eshell","lanes","logs"],e:["lanes_logs"],x:"The banner offers Switch off and Restart hetu. A floor record names the gate's new state. Free calls still work: a plugin's own storage, cache and topics need no gate.",c:["Banner","Floor record"],th:[11]},
   {t:"The way back",n:["human","trusted","carrier","loader"],e:["human_trusted","trusted_carrier","carrier_loader"],x:"Security changes never ask the gate, so a failed gate can't block the way out. Switching the gate off with a Confirm lets calls with power pass, still logged. Restart hetu tries the gate again.",c:["The way out never asks the gate"],th:[39]},
   {t:"A hang is different",n:["gate","lockm","loader"],e:["loader_lock"],x:"A gate that hangs at start freezes main. Its start marker is still there at the next boot, so that boot holds the gate failed and the trusted window offers try again or switch off. A hang after start freezes main until you force-quit, a known limit.",c:["Start marker","Known limit"],th:[39],bad:true}
  ]},
 {id:"replay",name:"Shell agent goes after security",sum:"An agent with a shell changes hetu's security state without you. What hetu catches and what it doesn't.",
  steps:[
   {t:"It edits the state",n:["shell","state"],e:["shell_state"],x:"The agent edits switches.json to switch a guard off. A program running as you can write the file, so nothing stops the edit. At the next start the hash line doesn't match. Edited switches fall back to every guard on and an edited plugin entry means that plugin doesn't load. Nothing else stops and hetu records the result.",c:["Caught at start","Fail closed"],th:[24]},
   {t:"It rewrites the hash too",n:["shell","state"],e:["shell_state"],x:"An agent that knows hetu rewrites the hash, puts back an older copy with its own hash or deletes the files so hetu starts on defaults. That isn't caught. hetu treats a program that targets it as out of scope: it can already read and edit your notes directly, so a stronger lock on the state alone would guard one door beside an open wall.",c:["Not caught","Accepted: detect only"],th:[24,25,55],bad:true},
   {t:"It tries to fool you instead",n:["shell","trusted","human"],e:["shell_ui"],x:"It could also inject code into hetu and show you one change in the trusted window while asking for another. Or it could drive the desktop and click Confirm itself. A program that targets hetu is out of scope and editing the state directly is easier.",c:["Out of scope","Accepted risk"],th:[58],bad:true},
   {t:"What is on record",n:["boot","lanes","logs"],e:["boot_lanes","lanes_logs"],x:"Every check at start goes in the event log. A program running as you can delete the log too, so the hash chain shows gaps and the optional cloud plugin keeps a copy that survives.",c:["Hash chain"],th:[11]}
  ]},
 {id:"hang",name:"A plugin hangs",sum:"The core measures and terminates, the watchdog decides and you can stop it too.",
  steps:[
   {t:"Heartbeat goes unanswered",n:["runtime","community"],e:["runtime_comm"],x:"The runtime pings every worker every 5 seconds. After three misses the plugin is marked unresponsive, not crashed.",c:["Heartbeat","Three misses"],th:[36]},
   {t:"Its roles count as down",n:["carrier","community","watchdog"],e:["comm_carrier","carrier_watchdog"],x:"Calls to it answer timeout at once and its events stop. Nothing is closed and plugins that depend on it keep running. It returns to ready if it answers again. The watchdog hears the facts.",c:["timeout at once"],th:[36]},
   {t:"The watchdog decides",n:["carrier","watchdog"],e:["watchdog_carrier"],x:"The watchdog labels the plugin by behavior, such as \"memory consuming\", since nobody can tell malicious from badly written from outside. It may stop or restart the plugin through watchdog actions only its holder may call.",c:["Label by behavior"],th:[36]},
   {t:"Or you stop it",n:["human","trusted","carrier"],e:["human_trusted","trusted_carrier"],x:"The plugin list in the trusted window stops or restarts any sandboxed plugin. Restarting widens nothing, so it needs no Confirm.",c:["Stop from the trusted window"],th:[36]},
   {t:"Terminate",n:["carrier","loader","runtime","community"],e:["carrier_loader","loader_runtime","runtime_comm"],x:"The loader stops the plugin and the runtime ends its worker with terminate(), which stops even a busy loop. A restart runs the bytes already verified as a new incarnation on a new port. The stop is recorded.",c:["terminate()","New incarnation"],th:[36]},
   {t:"If it floods instead",n:["community","carrier","watchdog"],e:["comm_carrier"],x:"The carrier counts every message at the way in. Messages over the rate are dropped with no reply and the watchdog hears once a second. A port over the flood cap is closed and the plugin is marked crashed.",c:["Rate counted at bind","Flood cap"],th:[36]}
  ]},
 {id:"writerun",name:"Plugin tries write-then-run",sum:"A malicious plugin with an exec grant tries to run code it wrote itself.",
  steps:[
   {t:"It writes a script into its storage",n:["community","carrier","storage","storefs"],e:["comm_carrier","carrier_storage","storage_fs"],x:"Storage is free and always granted, so writing helper.js into its own space succeeds.",c:["Own space only"],th:[46],bad:true},
   {t:"It asks to run it",n:["community","carrier","gate","exec"],e:["comm_carrier","carrier_gate","carrier_exec"],x:"Its manifest declared the exact command node <storage>/helper.js and you approved it with a Confirm. The string matches exactly.",c:["Exact match passes"],th:[46],bad:true},
   {t:"Refused",n:["exec","carrier","lanes"],e:["carrier_lanes"],x:"The exec plugin refuses any command that runs a file from storage or the luoshu as code. Files run as code must come from the signed package or the system. The refusal is recorded.",c:["Only signed package or system files run as code"],th:[46]},
   {t:"Even a clean command is pinned",n:["exec","osproc"],e:["exec_proc"],x:"Allowed commands run with an environment the core builds: absolute paths, a fixed working directory and no NODE_OPTIONS or similar.",c:["Clean environment"],th:[45]},
   {t:"The gate off changes nothing here",n:["exec","gate"],e:[],x:"With the gate off, the exec plugin still checks each call against the plugin's declared commands, along with the environment and write-then-run rules. Only your own switch, any command for that plugin, lifts the list, with a Confirm and a banner.",c:["Checked with the gate off too"],th:[45,46]}
  ]},
 {id:"direct",name:"Shell agent edits a note directly",sum:"An agent writes a note on disk, going around hetu.",
  steps:[
   {t:"It writes the file",n:["shell","luoshufs"],e:["shell_luoshu"],x:"An agent with a shell edits a note directly, bypassing leases and the luoshu plugin.",c:[],th:[10],bad:true},
   {t:"The watcher sees it",n:["luoshu","luoshufs","bus"],e:["luoshu_watch","luoshu_bus"],x:"The luoshu plugin's watcher compares the file with its own writes and publishes luoshu.outside. Subscribers that may read the note hear a signal and the path.",c:["Detection only"],th:[10]},
   {t:"Recorded as unknown",n:["gitp","carrier","history","osproc","shadow"],e:["hidden_carrier","carrier_history","history_proc","proc_shadow"],x:"The next commit to the shadow repo marks the change as made by an unknown writer, never under an agent's name. History keeps the version before.",c:["Attribution","Revertable"],th:[10]},
   {t:"No silent overwrite",n:["leases","luoshu","carrier"],e:["carrier_luoshu"],x:"If an agent holds a lease on that note, its next write against the old version fails the version check, so nothing is silently overwritten.",c:["Version check"],th:[2,10]}
  ]}
];
